/**
 * Hanover + Chesterfield meetings in the city model (Oct 23 2026).
 * BOS: the full official CivicClerk catalogs (CC_MEETINGS, generated by scripts/civicclerk-counties-build.py).
 * Schools + transcribed BOS meetings: hc-meetings-transcribed.json (written by the ingest; adds the
 * direct CivicClerk mp4 used for jump links, agenda and minutes links).
 */
import type { CityMeeting } from "./cities";
import { CC_MEETINGS } from "./civicclerk-counties-data";
import TRANSCRIBED from "./hc-meetings-transcribed.json";

const EXTRA = TRANSCRIBED as CityMeeting[];
const EXTRA_BY_ID = new Map(EXTRA.map((m) => [m.id, m]));

const fromCatalog = (venue: "hanover-bos" | "chesterfield-bos"): CityMeeting[] =>
  CC_MEETINGS[venue].map(
    (m) =>
      EXTRA_BY_ID.get(m.id) ?? {
        id: m.id,
        venue,
        title: m.title,
        date: m.date,
        dateLabel: m.dateLabel,
        duration: m.duration,
        provider: "civicclerk",
        playerUrl: m.href,
      },
  );

const catalogIds = new Set([...CC_MEETINGS["hanover-bos"], ...CC_MEETINGS["chesterfield-bos"]].map((m) => m.id));

export const HC_MEETINGS: CityMeeting[] = [
  ...fromCatalog("hanover-bos"),
  ...fromCatalog("chesterfield-bos"),
  ...EXTRA.filter((m) => !catalogIds.has(m.id)),
];
